1	import prisma from 'prisma/prisma';
2	import type { GameDayType } from 'prisma/zod/schemas/models/GameDay.schema';
3	import z from 'zod';
4	
5	import { getShortMonthName } from '@/lib/dates';
6	import { normalizeUnknownError } from '@/lib/errors';
7	import { toPounds } from '@/lib/money';
8	import gameDayService from '@/services/GameDay';
9	import playerService, { PlayerDisplayType } from '@/services/Player';
10	import {
11	    type PayDebtResult,
12	    PayDebtResultSchema,
13	} from '@/types/actions/PayDebt';
14	import { RecordHallHireInputSchema } from '@/types/actions/RecordHallHire';
15	import type { MoneyChartDatum, PlayerDebtsType } from '@/types/DebtType';
16	import { DebtsSummarySchema } from '@/types/DebtType';
17	
18	class MoneyService {
19	    /**
20	     * Returns all unpaid player game charges grouped by player.
21	     *
22	     * Each player is represented with their ID, name, and a list of unpaid
23	     * PlayerGameCharge transactions. Each unpaid charge includes the gameDayId
24	     * and amount owed for that specific game.
25	     *
26	     * @returns A promise that resolves to a DebtsSummaryType containing players
27	     * with their respective unpaid game charges and aggregate balance information
28	     */
29	    async getDebts() {
30	        try {
31	            // Fetch all player game charges first, then remove ones that have
32	            // already been paid with a matching PlayerPayment.
33	            const playerGameCharges = await prisma.transaction.findMany({
34	                where: {
35	                    type: 'PlayerGameCharge',
36	                    playerId: {
37	                        not: null,
38	                    },
39	                    gameDayId: {
40	                        not: null,
41	                    },
42	                },
43	                select: {
44	                    playerId: true,
45	                    gameDayId: true,
46	                    amountPence: true,
47	                },
48	            });
49	
50	            const playerPayments = await prisma.transaction.findMany({
51	                where: {
52	                    type: 'PlayerPayment',
53	                    playerId: {
54	                        not: null,
55	                    },
56	                    gameDayId: {
57	                        not: null,
58	                    },
59	                },
60	                select: {
61	                    playerId: true,
62	                    gameDayId: true,
63	                },
64	            });
65	
66	            const paidChargeKeys = new Set(
67	                playerPayments
68	                    .filter(
69	                        (payment) =>
70	                            payment.playerId != null &&
71	                            payment.gameDayId != null,
72	                    )
73	                    .map(
74	                        (payment) =>
75	                            `${payment.playerId!}:${payment.gameDayId!}`,
76	                    ),
77	            );
78	
79	            const unpaidCharges = playerGameCharges.filter((charge) => {
80	                // Prisma filters these out, but the generated type still includes null
81	                /* v8 ignore next */
82	                if (charge.playerId == null || charge.gameDayId == null)
83	                    return false;
84	
85	                return !paidChargeKeys.has(
86	                    `${charge.playerId}:${charge.gameDayId}`,
87	                );
88	            });
89	
90	            // Group debts (unpaid charges) by playerId
91	            const debtsByPlayer = new Map<
92	                number,
93	                {
94	                    player: PlayerDisplayType;
95	                    charges: { gameDay: GameDayType; amount: number }[];
96	                }
97	            >();
98	
99	            for (const charge of unpaidCharges) {
100	                const key = charge.playerId!;
101	                if (!debtsByPlayer.has(key)) {
102	                    const player = await playerService.getById(
103	                        charge.playerId!,
104	                    );
105	                    if (player == null) continue;
106	                    debtsByPlayer.set(key, {
107	                        player,
108	                        charges: [],
109	                    });
110	                }
111	
112	                const gameDay = await gameDayService.get(charge.gameDayId!);
113	                if (gameDay == null) continue;
114	
115	                const entry = debtsByPlayer.get(key)!;
116	                entry.charges.push({
117	                    gameDay,
118	                    amount: charge.amountPence,
119	                });
120	            }
121	
122	            // Build the players array with debts
123	            const players: PlayerDebtsType[] = [];
124	            for (const [, { charges, player }] of debtsByPlayer) {
125	                players.push({
126	                    player,
127	                    debts: charges.map((charge) => ({
128	                        gameDay: charge.gameDay,
129	                        amount: charge.amount,
130	                    })),
131	                });
132	            }
133	
134	            return DebtsSummarySchema.parse({
135	                players,
136	            });
137	        } catch (error) {
138	            throw normalizeUnknownError(error);
139	        }
140	    }
141	
142	    /**
143	     * Returns chart data grouped by month (when year > 0) or by year (when year
144	     * === 0 for all-time). Credits are transactions with negative amountPence
145	     * (money flowing in); debits are those with positive amountPence (money
146	     * flowing out).
147	     *
148	     * @param year - The year to filter transactions by (0 for all-time data)
149	     * @returns An array of chart data points with credits and debits grouped by
150	     * interval
151	     */
152	    async getChartData(year: number): Promise<MoneyChartDatum[]> {
153	        try {
154	            const { minId, maxId } =
155	                await gameDayService.getIdRangeForYear(year);
156	            if (minId === null || maxId === null) {
157	                return [];
158	            }
159	
160	            const playerPayments = await prisma.transaction.groupBy({
161	                by: ['gameDayId'],
162	                where: {
163	                    type: 'PlayerPayment',
164	                    gameDayId: {
165	                        gte: minId,
166	                        lte: maxId,
167	                    },
168	                },
169	                _sum: {
170	                    amountPence: true,
171	                },
172	            });
173	            const hallHire = await prisma.transaction.groupBy({
174	                by: ['gameDayId'],
175	                where: {
176	                    type: 'HallHire',
177	                    gameDayId: {
178	                        gte: minId,
179	                        lte: maxId,
180	                    },
181	                },
182	                _sum: {
183	                    amountPence: true,
184	                },
185	            });
186	
187	            const gameDays = await prisma.gameDay.findMany({
188	                where: {
189	                    id: {
190	                        gte: minId,
191	                        lte: maxId,
192	                    },
193	                },
194	                select: {
195	                    id: true,
196	                    date: true,
197	                },
198	            });
199	
200	            const accumulateTotals = (
201	                transactions: {
202	                    gameDayId: number | null;
203	                    _sum: { amountPence: number | null };
204	                }[],
205	                intervalByGameDayId: Map<number, number>,
206	                totalsByInterval: Map<
207	                    number,
208	                    { credits: number; debits: number }
209	                >,
210	            ) => {
211	                for (const row of transactions) {
212	                    if (row.gameDayId == null) {
213	                        continue;
214	                    }
215	
216	                    const interval = intervalByGameDayId.get(row.gameDayId);
217	                    if (interval == null) {
218	                        continue;
219	                    }
220	
221	                    const entry = totalsByInterval.get(interval) ?? {
222	                        credits: 0,
223	                        debits: 0,
224	                    };
225	                    const amountPence = row._sum.amountPence ?? 0;
226	                    if (amountPence > 0) {
227	                        entry.debits += toPounds(amountPence);
228	                    } else {
229	                        entry.credits += toPounds(Math.abs(amountPence));
230	                    }
231	                    totalsByInterval.set(interval, entry);
232	                }
233	            };
234	
235	            if (year > 0) {
236	                const monthByGameDayId = new Map<number, number>(
237	                    gameDays.map((gameDay): [number, number] => [
238	                        gameDay.id,
239	                        gameDay.date.getUTCMonth(),
240	                    ]),
241	                );
242	                const totalsByMonth = new Map<
243	                    number,
244	                    { credits: number; debits: number }
245	                >();
246	
247	                accumulateTotals(
248	                    playerPayments,
249	                    monthByGameDayId,
250	                    totalsByMonth,
251	                );
252	                accumulateTotals(hallHire, monthByGameDayId, totalsByMonth);
253	
254	                return [...totalsByMonth.entries()]
255	                    .sort(([a], [b]) => a - b)
256	                    .map(([month, totals]) => ({
257	                        interval: getShortMonthName(year, month + 1),
258	                        credits: totals.credits,
259	                        debits: totals.debits,
260	                    }));
261	            } else {
262	                const yearByGameDayId = new Map<number, number>(
263	                    gameDays.map((gameDay): [number, number] => [
264	                        gameDay.id,
265	                        gameDay.date.getUTCFullYear(),
266	                    ]),
267	                );
268	                const totalsByYear = new Map<
269	                    number,
270	                    { credits: number; debits: number }
271	                >();
272	
273	                accumulateTotals(playerPayments, yearByGameDayId, totalsByYear);
274	                accumulateTotals(hallHire, yearByGameDayId, totalsByYear);
275	
276	                return [...totalsByYear.entries()]
277	                    .sort(([a], [b]) => a - b)
278	                    .map(([yearKey, totals]) => ({
279	                        interval: String(yearKey),
280	                        credits: totals.credits,
281	                        debits: totals.debits,
282	                    }));
283	            }
284	        } catch (error) {
285	            throw normalizeUnknownError(error);
286	        }
287	    }
288	
289	    /**
290	     * Charges a player for a game by creating a transaction record.
291	     *
292	     * Validates inputs and persists the amount with the provided note.
293	     *
294	     * @param playerId - The unique identifier of the player to charge.
295	     * @param amount - The amount to charge.
296	     * @param note - A short description for the charge (max 255 characters).
297	     * @throws Will rethrow any validation or persistence errors encountered.
298	     */
299	    async charge(
300	        playerId: number,
301	        gameDayId: number,
302	        amount: number,
303	        note?: string,
304	    ): Promise<void> {
305	        try {
306	            const parsed = z
307	                .object({
308	                    playerId: z.number().int().min(1),
309	                    gameDayId: z.number().int().min(1),
310	                    amount: z.number().int().positive().max(49900),
311	                    note: z.string().max(255).optional(),
312	                })
313	                .parse({ playerId, gameDayId, amount, note });
314	
315	            await prisma.transaction.upsert({
316	                where: {
317	                    type_playerId_gameDayId: {
318	                        type: 'PlayerGameCharge',
319	                        playerId: parsed.playerId,
320	                        gameDayId: parsed.gameDayId,
321	                    },
322	                },
323	                update: {
324	                    amountPence: parsed.amount,
325	                    note: parsed.note,
