import { Notifications } from '@mantine/notifications';
import type { Meta, StoryObj } from '@storybook/nextjs-vite';
import { fn, within } from 'storybook/test';

import {
    createMockGameInvitationResponseDetails,
    defaultGameInvitationResponseDetails,
} from '@/tests/mocks/data/gameInvitationResponse';
import { SubmitGameInvitationResponseProxy } from '@/types/actions/SubmitGameInvitationResponse';

import { GameInvitationResponseForm } from './GameInvitationResponseForm';

const mockSubmitGameInvitationResponse =
    fn<SubmitGameInvitationResponseProxy>().mockResolvedValue({
        ...defaultGameInvitationResponseDetails,
        id: 1,
    });

const meta = {
    title: 'Forms/GameInvitationResponseForm',
    component: GameInvitationResponseForm,
    decorators: [
        (Story) => (
            <>
                <Notifications />
                <Story />
            </>
        ),
    ],
    args: {
        onSubmitGameInvitationResponse: mockSubmitGameInvitationResponse,
    },
    parameters: {
        layout: 'centered',
    },
    tags: ['autodocs'],
} satisfies Meta<typeof GameInvitationResponseForm>;

export default meta;
type Story = StoryObj<typeof meta>;

export const EmptyResponse: Story = {
    args: {
        details: createMockGameInvitationResponseDetails({
            response: null,
            comment: null,
        }),
    },
};

export const SubmitResponse: Story = {
    args: {
        details: createMockGameInvitationResponseDetails(),
    },
    play: async function ({ canvasElement, userEvent, viewMode }) {
        if (viewMode === 'docs') return;

        const canvas = within(canvasElement);
        const responseSelect = await canvas.findByRole('combobox', {
            name: /Response/i,
        });
        await userEvent.click(responseSelect);
        const dropdown = await within(
            canvasElement.ownerDocument.body,
        ).findByRole('listbox');
        await userEvent.click(
            await within(dropdown).findByRole('option', {
                name: 'Yes',
                hidden: true,
            }),
        );
        await userEvent.click(await canvas.findByLabelText(/Goalie/i));
        await userEvent.type(
            await canvas.findByLabelText(/Optional comment/i),
            'Count me in.',
        );
        await userEvent.click(
            await canvas.findByRole('button', { name: /Save Response/i }),
        );

        const body = canvasElement.ownerDocument.body;
        await within(body).findByText('Response saved', {}, { timeout: 6000 });
    },
};

import { ConfigSchema, ConfigType } from '@/types/config';

const rawConfig: ConfigType = {
    minGamesForAveragesTable: 10,
    minRepliesForSpeedyTable: 10,
    contactEmailDestination: 'footy@toastboy.co.uk',
    sessionRevalidate: 60000,
    notificationAutoClose: 4000,
    notificationIconSize: 18,
    organiserPhoneNumber: '07802 346128',
    defaultGameCostPence: 600,
    defaultHallCostPence: 4935,
    trophyDisplayThreshold: 5,
    tableVisibleRows: 15,
};

// App-wide configuration object which is runtime-validated using zod. If this
// throws it will surface early during server start / build so misconfiguration
// is caught quickly.

export const config = ConfigSchema.parse(rawConfig);

